// AUTO-GENERATED: edit sources under src/web/, then npm run build.
export const HTML:string = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\"/><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"/>\n<meta name=\"theme-color\" content=\"#f6f8fb\"/><meta name=\"description\" content=\"Aurora: avisos acadêmicos transformados em tarefas e compromissos com privacidade.\"/>\n<link rel=\"manifest\" href=\"/assets/manifest.webmanifest\"/><link rel=\"icon\" type=\"image/png\" sizes=\"192x192\" href=\"/assets/icons/aurora-192.png\"/><link rel=\"apple-touch-icon\" href=\"/assets/icons/aurora-192.png\"/><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"/><meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\"/><title>Aurora — Sua vida acadêmica, organizada</title>\n<link rel=\"stylesheet\" href=\"/assets/aurora.css\"/>\n<script type=\"module\" src=\"/assets/aurora.js\"></script>\n</head>\n<body>\n<div class=\"shell\">\n<header class=\"header\">\n  <a href=\"/\" class=\"brand\" aria-label=\"Aurora início\"><span class=\"logo\" aria-hidden=\"true\">✦</span><span><strong>Aurora</strong><small>seu tempo, com clareza</small></span></a>\n  <div class=\"header-end\"><button type=\"button\" id=\"install-app\" class=\"button outline small hide\">Instalar app</button><span class=\"tiny-dot\" aria-hidden=\"true\"></span><span class=\"header-tag\">Instância pessoal</span><button type=\"button\" id=\"logout\" class=\"button outline small hide\">Sair</button></div>\n</header>\n<main>\n <div id=\"offline-banner\" class=\"connection-banner hide\" role=\"status\">Você está sem conexão. O Aurora não mostra dados antigos como se fossem atuais.</div><section id=\"login-view\" class=\"auth-view hide\" aria-labelledby=\"login-title\">\n  <div class=\"auth-illustration\" aria-hidden=\"true\"><div class=\"sun-mark\">✦</div></div>\n  <div class=\"auth-box\"><p class=\"eyebrow\">BEM-VINDO DE VOLTA</p><h1 id=\"login-title\">Tudo que importa na faculdade, em um só lugar.</h1><p class=\"muted\">Entre com a senha desta instalação. O Aurora não pede a senha do seu e-mail.</p>\n   <form id=\"login-form\"><label for=\"passphrase\">Senha da instalação</label><input id=\"passphrase\" name=\"passphrase\" type=\"password\" autocomplete=\"current-password\" minlength=\"20\" required placeholder=\"Digite sua senha segura\"/><button class=\"button primary full\" type=\"submit\">Entrar no Aurora <span aria-hidden=\"true\">→</span></button></form><p class=\"small muted\">Sua senha foi definida durante a hospedagem individual.</p><p class=\"small\"><a href=\"/instalar\" target=\"_blank\" rel=\"noopener\">Como criar sua instalação pessoal</a> · <a href=\"/demonstracao\" target=\"_blank\" rel=\"noopener\">Conhecer sem conectar e-mail</a></p><div id=\"login-error\" role=\"alert\" class=\"error hide\"></div></div>\n </section>\n <section id=\"workspace\" class=\"hide\">\n  <div class=\"hero\"><div><p class=\"eyebrow\">SEU ESPAÇO ACADÊMICO</p><h1 id=\"hero-title\">Bom ter você por aqui.</h1><p class=\"muted\">Avisos importantes organizados, sem complicação.</p></div><button type=\"button\" id=\"sync\" class=\"button primary\">↻ Verificar e-mails</button></div>\n  <nav class=\"tabs\" role=\"tablist\" aria-label=\"Navegação principal\"><button id=\"tab-home\" role=\"tab\" aria-controls=\"panel-home\" aria-selected=\"true\" tabindex=\"0\" class=\"tab active\" data-tab=\"home\">Visão geral</button><button id=\"tab-items\" role=\"tab\" aria-controls=\"panel-items\" aria-selected=\"false\" tabindex=\"-1\" class=\"tab\" data-tab=\"items\">Atividades e avisos</button><button id=\"tab-settings\" role=\"tab\" aria-controls=\"panel-settings\" aria-selected=\"false\" tabindex=\"-1\" class=\"tab\" data-tab=\"settings\">Conexões</button><button id=\"tab-guide\" role=\"tab\" aria-controls=\"panel-guide\" aria-selected=\"false\" tabindex=\"-1\" class=\"tab\" data-tab=\"guide\">Instalação e ajuda</button></nav>\n  <div id=\"global-error\" class=\"error hide\" role=\"alert\"></div>\n  <section class=\"tab-view\" id=\"panel-home\" role=\"tabpanel\" aria-labelledby=\"tab-home\" tabindex=\"0\"><div class=\"stats\"><article class=\"metric\"><small>Pendentes de revisão</small><strong id=\"stat-review\">—</strong><span>Você decide antes de criar</span></article><article class=\"metric\"><small>Atividades</small><strong id=\"stat-tasks\">—</strong><span>Com prazo conhecido</span></article><article class=\"metric\"><small>Itens na agenda</small><strong id=\"stat-synced\">—</strong><span>Sincronizados pelo Aurora</span></article></div>\n  <section id=\"onboarding\" class=\"card onboarding\"><div class=\"onboard-head\"><div><p class=\"eyebrow\">COMECE AQUI</p><h2>Configure em poucos passos</h2><p class=\"muted\">Seus dados continuam na sua instalação.</p></div><span class=\"step-pill\">PASSO <span id=\"setup-step\">1</span> DE 3</span></div><div class=\"steps\"><div class=\"step active\"><span>1</span><p>Conectar conta</p></div><div class=\"step\"><span>2</span><p>Autorizar</p></div><div class=\"step\"><span>3</span><p>Organizar</p></div></div><div id=\"provider-selection\" class=\"provider-cards\"></div><p class=\"muted micro\">Você será direcionado à página oficial de consentimento do provedor. A universidade pode exigir aprovação adicional.</p></section>\n  <section class=\"card\"><p id=\"onboarding-live-status\" role=\"status\" class=\"muted small\">A preparação será conferida com os serviços da instalação.</p><button type=\"button\" id=\"onboarding-check\" class=\"button outline small\">Conferir etapas da instalação</button></section><section class=\"card\"><div class=\"card-title\"><h2>Próximos compromissos</h2><span class=\"muted small\">Somente datas confirmadas</span></div><div id=\"upcoming\"></div></section>\n  <p id=\"quota-status\" class=\"muted small\" role=\"status\">Os limites de sincronização serão exibidos após entrar.</p><section class=\"card\"><div class=\"card-title\"><h2>Estado da automação</h2><span class=\"small muted\">Verificação a cada 3 min; contas sem atraso aguardam cerca de 15 min*</span></div><div id=\"connections-home\"></div><p class=\"muted micro\">*Quando a hospedagem e o agendador estiverem ativos. Uma falha ou bloqueio aparecerá aqui.</p></section></section>\n  <section id=\"panel-guide\" role=\"tabpanel\" aria-labelledby=\"tab-guide\" tabindex=\"0\" class=\"tab-view hide\"><div class=\"section-head\"><h2 id=\"guide-heading\">Instalar em outros dispositivos</h2><p class=\"muted\">O mesmo Aurora pode ser aberto no computador e no celular. A hospedagem pessoal fica na nuvem e a autorização do e-mail não se repete por aparelho.</p></div><section class=\"card\"><h2>Instalar o aplicativo</h2><p id=\"install-instructions\" role=\"status\">Abra o Aurora em um navegador compatível para instalar.</p><button type=\"button\" class=\"button primary hide\" id=\"install-guide-btn\">Instalar neste dispositivo</button><p class=\"muted small\">No iPhone, use Compartilhar → Adicionar à Tela de Início. No computador, Chrome e Edge geralmente oferecem instalação pelo menu do navegador.</p></section><section class=\"card\"><h2>Estado da instalação</h2><div id=\"diagnostics\" role=\"status\">Abra a seção após entrar para conferir os serviços.</div><button type=\"button\" id=\"skip-push-onboarding\" class=\"button outline small\">Continuar sem notificações próprias</button><button type=\"button\" id=\"refresh-diagnostics\" class=\"button outline\">Verificar novamente</button></section><section class=\"card\"><h2>Proteção de dados</h2><p>O Aurora não salva mensagens, tarefas, calendários, tokens ou informações pessoais no cache offline. Quando o aparelho ficar sem conexão, exibirá apenas um aviso neutro.</p><p>As notificações principais são as configuradas no seu Google Calendar ou Outlook Calendar. Não existe envio de e-mails a serviços de IA por padrão.</p></section></section>\n  <section id=\"panel-items\" role=\"tabpanel\" aria-labelledby=\"tab-items\" tabindex=\"0\" class=\"tab-view hide\"><div class=\"section-head\"><h2>Atividades e avisos</h2><p class=\"muted\">Confira o que foi extraído. Nenhuma data incerta vira evento sem sua confirmação.</p></div><div class=\"item-filters\"><div><label for=\"item-search\">Buscar nos últimos comunicados</label><input id=\"item-search\" type=\"search\" autocomplete=\"off\" maxlength=\"140\" placeholder=\"Ex.: estágio, prova, relatório\"></div><div><label for=\"item-filter\">Mostrar</label><select id=\"item-filter\"><option value=\"all\">Todos</option><option value=\"review\">Para revisar</option><option value=\"task\">Atividades</option><option value=\"event\">Compromissos</option><option value=\"notice\">Avisos</option></select></div></div><p class=\"muted micro\">Mostrando até os 100 registros mais recentes; exportação disponível em Conexões.</p><div id=\"items-list\"></div><div class=\"card\"><h2>Ações de calendário que precisam de atenção</h2><p class=\"muted small\">Após uma resposta ambígua, o Aurora interrompe reenvios para evitar duplicatas.</p><div id=\"outbox-list\"></div></div></section>\n  <section id=\"panel-settings\" role=\"tabpanel\" aria-labelledby=\"tab-settings\" tabindex=\"0\" class=\"tab-view hide\"><div class=\"section-head\"><h2>Suas conexões</h2><p class=\"muted\">Cada conta utiliza autorização independente, sem compartilhar sua senha.</p></div><div id=\"connections-settings\" class=\"card\"></div>\n  <div class=\"card\"><h2>Personalizar lembretes</h2><p class=\"muted small\">Aplicável às próximas criações na agenda. Os prazos sem hora são eventos de dia inteiro, sem horário de entrega presumido.</p><form id=\"preferences-form\"><label for=\"pref-event\">Avisar antes de compromissos</label><select id=\"pref-event\"><option value=\"0\">No horário</option><option value=\"30\">30 minutos</option><option value=\"60\">1 hora</option><option value=\"120\">2 horas</option><option value=\"1440\">1 dia</option><option value=\"10080\">1 semana</option></select><label for=\"pref-task\">Avisar antes de prazos</label><select id=\"pref-task\"><option value=\"0\">No dia</option><option value=\"1440\">1 dia</option><option value=\"2880\">2 dias</option><option value=\"10080\">1 semana</option></select><button type=\"submit\" class=\"button primary\">Salvar lembretes</button></form></div><div class=\"card\"><h2>Notificações do Aurora (opcionais)</h2><p class=\"muted small\">Os lembretes da agenda continuam sendo o canal principal. Se habilitar, este dispositivo poderá receber avisos genéricos de novas revisões; o texto do e-mail nunca aparece na tela bloqueada.</p><p id=\"push-status\" role=\"status\">Notificações próprias desativadas até você autorizar.</p><div class=\"row-actions\"><button type=\"button\" class=\"button outline\" id=\"push-enable\">Ativar neste aparelho</button><button type=\"button\" class=\"button outline\" id=\"push-disable\">Desativar neste aparelho</button></div><form id=\"quiet-hours-form\"><label for=\"quiet-start\">Silêncio a partir das</label><input id=\"quiet-start\" type=\"time\" value=\"22:00\" required/><label for=\"quiet-end\">Até as</label><input id=\"quiet-end\" type=\"time\" value=\"07:00\" required/><label for=\"quiet-zone\">Fuso horário (IANA)</label><input id=\"quiet-zone\" type=\"text\" value=\"America/Sao_Paulo\" maxlength=\"60\" required/><button class=\"button outline small\" type=\"submit\">Salvar horários de silêncio</button></form><p class=\"muted micro\">O botão só solicita permissão quando você tocar nele. No iPhone, instale primeiro o Aurora na Tela de Início. A aceitação pelo gateway não garante a entrega no aparelho.</p></div><div class=\"card\"><h2>Adicionar outra conta</h2><div id=\"other-providers\" class=\"provider-cards\"></div></div><div class=\"card\"><h2>Hospedagem e privacidade</h2><p>Esta instalação guarda apenas dados necessários à organização. O corpo completo do e-mail não é publicado no calendário; seus tokens ficam cifrados no servidor.</p><p class=\"muted small\">Os calendários criados permanecem na sua conta mesmo após desconectar. Para revogar permissões, visite a segurança da conta Google ou Microsoft.</p><button type=\"button\" id=\"export-data\" class=\"button outline\">Exportar todos os meus dados</button></div><div class=\"card\"><h2>Sessões em outros aparelhos</h2><p class=\"muted small\">Você pode revogar o acesso de outro dispositivo a qualquer momento. Isso não desconecta suas contas de e-mail.</p><div id=\"sessions-list\"></div><button type=\"button\" id=\"refresh-sessions\" class=\"button outline small\">Atualizar sessões</button></div><div class=\"card\"><h2>Como funciona a instalação</h2><ol class=\"guide\"><li>O responsável cria a instância gratuita pela Cloudflare.</li><li>Configura os segredos e registra o aplicativo OAuth nos provedores desejados.</li><li>Você abre esta página, escolhe Gmail ou Outlook e autoriza as permissões oficiais.</li><li>Os avisos passam a ser organizados automaticamente.</li></ol><p class=\"small muted\">Um deploy simples é possível; a aprovação de APIs institucionais não pode ser automatizada pelo Aurora.</p></div>\n  </section>\n </section>\n</main>\n<footer>Feito para organizar — não para decidir por você. <span>✦ Aurora 2.2</span></footer>\n</div>\n<div id=\"review-modal\" class=\"dialog-backdrop hide\" role=\"presentation\"><section class=\"dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"review-heading\"><h2 id=\"review-heading\">Revisar informação</h2><p class=\"muted small\" id=\"review-context\"></p><form id=\"review-form\"><label for=\"review-kind\">O que deseja criar?</label><select id=\"review-kind\"><option value=\"event\">Compromisso com dia e hora</option><option value=\"task\">Atividade com prazo</option></select><label for=\"review-date\">Data</label><input id=\"review-date\" type=\"date\" required/><div id=\"review-time-wrap\"><label for=\"review-time\">Horário</label><input id=\"review-time\" type=\"time\" required value=\"09:00\"/></div><div class=\"dialog-actions\"><button id=\"review-cancel\" type=\"button\" class=\"button outline\">Cancelar</button><button type=\"submit\" class=\"button primary\">Confirmar e salvar</button></div></form></section></div>\n<div id=\"change-review-modal\" class=\"dialog-backdrop hide\" role=\"presentation\"><section class=\"dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"change-review-title\"><h2 id=\"change-review-title\">Alterar compromisso existente</h2><p id=\"change-review-summary\" class=\"muted small\"></p><p class=\"muted small\">Confira o e-mail original. O Aurora não associa automaticamente comunicados de remarcação a eventos existentes.</p><form id=\"change-review-form\"><label for=\"change-target\">Qual compromisso esta mensagem altera?</label><select id=\"change-target\" required></select><label for=\"change-action\">O que aconteceu?</label><select id=\"change-action\"><option value=\"update\">Foi remarcado</option><option value=\"cancel\">Foi cancelado</option></select><div id=\"change-new-date\"><label for=\"change-date\">Nova data</label><input id=\"change-date\" type=\"date\" required><div id=\"change-new-time\"><label for=\"change-time\">Novo horário</label><input id=\"change-time\" type=\"time\" required value=\"09:00\"></div></div><div class=\"dialog-actions\"><button type=\"button\" id=\"change-review-close\" class=\"button outline\">Voltar</button><button type=\"submit\" class=\"button primary\">Confirmar alteração</button></div></form></section></div>\n</body></html>\n";
